"ex26_mob_leg_swing_sagittal":{"foc":[["29cmpb6ah3h","3nku5qrj2i","wmm1sldi7w","zcf98pqfkd"],"Noha se kývá z kyčle. Trup stojí.","The leg swings from the hip. The torso stays still."],"pos":[["1aztjom2kjv","bo0az9nt9q","sur6h78kzo","vgzi66z4ym"],"Stoj bokem k opoře, jedna ruka se drží. Vnější noha odlehčená.","Stand side-on to a support, one hand holding on. The outside leg unweighted."],"exe":[["1gn4z77wp9l","1nfb8eiukfw","1u251e73tal","z6z0svl13n"],"Kývej nohou plynule vpřed a vzad. Koleno skoro natažené.","Swing the leg smoothly forward and back. Knee almost straight."],"wat":[["29i5zeatmjh","g8i6asqjcn","q9n22misbe","rhj31jin5"],"Začni malým obloukem. Neprohýbej se v bedrech.","Start with a small arc. Don't arch the lower back."],"pro":[["1ph5pmsbn0u","1r2fsrb2cpb","xt9q6onbgl","ys5fmipjlp"],"Lehčí: menší kyv. Těžší: větší oblouk.","Easier: a smaller swing. Harder: a bigger arc."],"n":[["6zkrrakkoi"],"Kývání nohou vpřed a vzad","Front-to-Back Leg Swings"]},
"ex26_mob_lumbar_locked":{"foc":[["1f1wgmzhy1","1iefwjba1fp","1wvmedrtcgc","2dy5gtlnlvl"],"Otáčí se hrudník. Pánev sedí u pat.","The chest rotates. The pelvis sits by the heels."],"pos":[["1pfab94lmzq","1uqhfsdpze6","250drhcsy9v","pdb8hso523"],"Klek se zadkem u pat. Jedno předloktí na zemi, druhá ruka za hlavou.","Kneel with hips by the heels. One forearm on the floor, the other hand behind the head."],"exe":[["1icltrgugav","24sjh6j9r0a","2b4egibukwx","5q1lu78n8z"],"Pomalu otoč hrudník a volný loket ke stropu. Vrať se.","Slowly turn the chest and the free elbow to the ceiling. Return."],"wat":[["15trc30ec10","24eaisu03tr","kul6m98xd9","rz4kof6th9"],"Zadek se nezvedá od pat. Netahej za hlavu.","The hips don't lift off the heels. Don't pull on the head."],"pro":[["1iugsmn6v5k","1zyuc6vczqr","br8fqm8gkv","ur2qksmtv6"],"Lehčí: menší otočení. Těžší: krátká výdrž nahoře.","Easier: a smaller turn. Harder: a short hold at the top."]},
"ex26_mob_pendulum":{"foc":[["1e9ju6g6nag","1yaalv52te","2b9unxkfvnn"],"Paže visí jako provaz. Kýve ji tělo, ne rameno.","The arm hangs like a rope. The body swings it, not the shoulder."],"pos":[["1dzky6vmohj","2ay7ayyihfs","zhzcf1pls5"],"Jedna ruka opřená o stůl, mírný předklon. Druhá paže volně visí.","One hand resting on a table, a slight forward lean. The other arm hangs loose."],"exe":[["1u5zqsp96qw","1yaalv52te","6w7xj0istp","ml3r4hasj8"],"Přenášením váhy rozkývej visící paži vpřed a vzad nebo do malých kruhů.","Shift your weight to swing the hanging arm forward and back, or in small circles."],"wat":[["114cagvc40i","1oqcy6rk1xx","23sbflad1dc"],"Rameno nepomáhá silou. Malý rozsah. Bez bolesti.","The shoulder doesn't drive it. A small range. No pain."],"pro":[["1b7m0ny3s3b","1ju69qkkg99","i5ms3acxb1"],"Lehčí: menší kyv. Těžší: o něco větší kruhy.","Easier: a smaller swing. Harder: slightly bigger circles."],"n":[["gzsi98uw0m"],"Kyvadlo paže","Shoulder Pendulum"]},
"ex26_mob_pike_compression":{"foc":[["4gmurylbjk","znncvqmr7e","zw8i6pbetg"],"Pata jde nahoru, koleno zůstává propnuté.","The heel lifts, the knee stays locked."],"pos":[["1fa5glz6yf4","1mqekdedm8f","elvgbv8ime"],"Sed. Jedna noha natažená, druhé koleno přitažené rukama k trupu.","Sit. One leg straight, the other knee hugged to the torso."],"exe":[["1715mlyr1mk","23fijo6261t","2bftoaap4ik","2fcj7yu3t74"],"Zvedni patu natažené nohy kousek nad zem a pomalu ji polož.","Lift the heel of the straight leg slightly off the floor and lower it slowly."],"wat":[["13u0dh4megs","1x86otsbdw4","qezh8u9a82","ue6mkeygl9"],"Nezakláněj se. Koleno se nekrčí. Při křeči povol.","Don't lean back. The knee doesn't bend. Release if you cramp."],"pro":[["13l3jmetjg2","2a0xurxjlub","dahfxxz6am"],"Lehčí: menší zdvih. Těžší: ruce na zemi blíž ke kolenu.","Easier: a smaller lift. Harder: hands on the floor closer to the knee."],"n":[["pcp0mmt8fo"],"Zvedání natažené nohy v sedu","Seated Single-Leg Lift"]},
