"ex26_py_single_zigzag_back":{"foc":[["10hwjjncn26","12utxgqdq36","1ucz60tna7j","24f87bfd5i9"],"Stejná noha, přes čáru a pozpátku.","Same leg, across the line, going backward."],"pos":[["2eg0i9zs1v8","g4k3e5i5vt","gt7wuysfbt","kezoih5urs"],"Stoj na jedné noze vedle čáry. Volná dráha za tebou.","Stand on one leg beside a line. A clear lane behind you."],"exe":[["10p07r7psyv","1ewownucyqg","1uj6nhch4or","23m3rpy6f8r"],"Malými poskoky přeskakuj čáru a postupuj vzad. Dopadej na stejnou nohu. Poslední dopad zastav.","Hop the line in small hops while moving backward. Land on the same leg. Stick the last landing."],"wat":[["13nfw8rojsy","1jq6bjkrcpj","1xq5cs0aqf3","2bgeim0g6yq"],"Zkontroluj prostor za sebou. Koleno nepadá dovnitř. Jen s trenérem.","Check the space behind you. Knee doesn't cave in. Only with a coach."],"pro":[["19mereezk1z","1ipnmgyfif3","1z84h5on92p","2ubfffysta"],"Lehčí: stejné vpřed. Těžší: krátká řada bez pauzy.","Easier: the same going forward. Harder: a short run with no pause."],"n":[["1j1guh75xvh"],"Poskoky přes čáru jednonož vzad","Single-Leg Backward Crossover Hops"]},
"ex26_py_skip_backward":{"foc":[["19bvj8t2988","1wj3re1clwo","fa8n11eovd","ojsg6qc9km"],"Krok, poskok. Rytmus drž i pozpátku.","Step, hop. Keep the rhythm going backward."],"pos":[["l1zy1zdv4c","nbdzr11dyy","sn9h9yx9e","w1mxjbe86d"],"Rovná volná dráha za tebou. Stoj vzpřímeně.","A clear flat lane behind you. Stand tall."],"exe":[["1vfrnlrsg79","82ilzgm6qv","fa8n11eovd","pj25h0x8o1"],"Krok vzad, nízký poskok na té noze a dopad na ni. Přestup na druhou a opakuj.","Step back, a low hop on that leg and land on it. Step to the other and repeat."],"wat":[["4nexrrpnu4","9nkezucfr7","9udu5mj3ms","v4w57cpp1"],"Zkontroluj si prostor za sebou. Poskoky nízké. Neotáčej trup.","Check the space behind you. Keep hops low. Don't twist the torso."],"pro":[["18u75cjq6dk","1rnsu35n6j","1vz74u35hoo","u9yy4hpws8"],"Lehčí: chůze vzad s výponem. Těžší: plynulý rytmus bez zastavení.","Easier: backward walk with a calf raise. Harder: a smooth unbroken rhythm."],"n":[["1a3bomtrxia"],"Skipping vzad","Backward Skip"]},
"ex26_py_skip_distance":{"foc":[["1ua83mnupr6","26kvz9fu1at","u0di2liig6","wlsacsntt0"],"Odraz dopředu. Dlouhý let, měkký dopad.","Drive forward. Long flight, soft landing."],"pos":[["1dxqoz69xgq","6bc2qea2ra","ovjcgua39i","w9mp5j0q74"],"Rovná neklouzavá dráha s místem na doběh.","A flat non-slip lane with room to slow down."],"exe":[["22zcrli7b39","25udoq3g6o3","95aq1uwua7","b7654dkbtc"],"Vykroč, odraz se z té nohy vpřed a dopadni na ni. Krok na druhou a opakuj. Paže pracují proti nohám.","Step, drive forward off that leg and land on it. Step to the other and repeat. Arms work opposite the legs."],"wat":[["15sx23qtpbt","1aef4mf2zkv","22zwpbhw1a1","4pl565ed0e"],"Nedopadej tvrdě. Trup vzpřímený. Délku přidávej postupně.","No hard landings. Stay tall. Add distance gradually."],"pro":[["2a9sqbpzel9","l1zu1gyfje","msfv32e43","qohjkj67r5"],"Lehčí: běžecký skipink A. Těžší: delší let ve stejném rytmu.","Easier: A-skip. Harder: longer flight at the same rhythm."],"n":[["1v427t8dc5t"],"Skipping do dálky","Power Skip for Distance"]},
"ex26_py_skip_height":{"foc":[["1gc85uhqimn","1q3vqlebolw","1ziynftrmpg","lje0rxhw7l"],"Odraz nahoru. Koleno letí před tělo.","Drive up. The knee punches in front."],"pos":[["8qfn0zgobh","fqo5cci3wz","j33tvmcis1","szgg4ukla4"],"Rovná neklouzavá dráha s místem na doběh.","A flat non-slip lane with room to slow down."],"exe":[["152nvx6ike5","1m38fib9gmv","29yvebc2qys","edp2x55imi"],"Vykroč a odraz se z té nohy hlavně nahoru. Volné koleno zvedni před sebe. Dopadni na odrazovou nohu a vystřídej.","Step and drive mostly upward off that leg. Lift the free knee in front. Land on the take-off leg and switch."],"wat":[["181owb4uouz","24vb3eqwi6x","5g52ahj2ve","usta1z6xrl"],"Dopad měkký a tichý. Nezakláněj se. Vpřed postupuj jen málo.","Soft, quiet landings. Don't lean back. Travel forward only a little."],"pro":[["1k7zg3dtj1l","1r4yurl0qwd","28y09zu9bmc","2e8tiuh4r2z"],"Lehčí: nízký skipping. Těžší: vyšší odraz ve stejném rytmu.","Easier: low skipping. Harder: a higher drive at the same rhythm."],"n":[["wu6qopossf"],"Skipping do výšky","Power Skip for Height"]},
"ex26_py_skip_lateral":{"foc":[["57znf3dr57","8kg2ab4gxc","hg80aee13l","vl3ni3747h"],"Boční krok a nízký odraz. Nohy se nekříží.","A side step and a low hop. The legs don't cross."],"pos":[["1lvig095mxl","1tmahx1ju80","ilvtexdqca","k7bk6sxi9w"],"Stoj bokem ke směru pohybu, chodidla na šířku ramen.","Stand side-on to the direction of travel, feet shoulder-width."],"exe":[["1g3zd2y7rzu","2aj19e6oupq","2b346dndawj","f7xdhxlu5r"],"Posouvej se do strany v rytmu krok–poskok. Zadní noha následuje přední.","Travel sideways in a step-hop rhythm. The trailing leg follows the lead."],"wat":[["1epzrmiz6o0","85tph51jdw","msqpnt1b3d","vsweowrugf"],"Chodidla se nespojí ani nezkříží. Hrudník míří vpřed.","Feet don't meet or cross. The chest faces forward."],"pro":[["1a9qf5it912","2e4nrtjrws1","2ff4dmzz06g","dug6ovanpf"],"Lehčí: boční přísuny bez poskoku. Těžší: plynulejší rytmus.","Easier: side shuffles with no hop. Harder: a smoother rhythm."],"n":[["rrm726byb"],"Skipping bokem","Lateral Skip"]},
"ex26_py_square_double":{"foc":[["1pejm1ri9ip","20yjpnfd0ci","2e199repuzd","4n9dsg86gu"],"Čtyři rohy snožmo. Hrudník míří pořád stejně.","Four corners on two feet. The chest keeps facing the same way."],"pos":[["18yvb4llmcx","24muakmrdi9","2a24vxnokjp","2eptttnpf0z"],"Stoj v rohu malého čtverce, chodidla u sebe.","Stand at a corner of a small square, feet together."],"exe":[["1ntye2xy9mc","1vtci86rx4y","1ztdkg9xaft","2b3snjwqas2"],"Skoč vpřed, do strany, vzad a zpátky do strany. Dopadej na obě nohy.","Jump forward, sideways, back and sideways again. Land on both feet."],"wat":[["1thdxlzs9c3","1vlmmdawd05","25h3amocqqb","rx7oua2gzk"],"Neotáčej se. Kolena nepadají dovnitř.","Don't turn. Knees don't cave in."],"pro":[["27z6tf6e5kt","299k9bfupi8","8901ewokqi","dn23xx4d32"],"Lehčí: projdi čtverec krokem. Těžší: celý čtverec bez pauzy.","Easier: walk the square. Harder: the whole square with no pause."],"n":[["26rf90ev20g"],"Přeskoky do čtverce snožmo","Square Hops"]},
